(x, y, t) => {
  const cx = 240, cy = 120;
  const wells = [
    [160+Math.sin(t*0.4)*120, 80+Math.cos(t*0.3)*60, 1.2+Math.sin(t*0.5)*0.4],
    [320+Math.cos(t*0.35)*100, 160+Math.sin(t*0.45)*70, 0.9+Math.cos(t*0.6)*0.3],
    [240+Math.sin(t*0.25+2)*140, 120+Math.cos(t*0.4+1)*90, 1.4+Math.sin(t*0.3)*0.5],
    [100+Math.cos(t*0.5+1)*60, 200+Math.sin(t*0.4+3)*40, 0.7],
    [380+Math.sin(t*0.3+4)*70, 50+Math.cos(t*0.6+2)*50, 1.1+Math.cos(t*0.4)*0.3]
  ];
  let fx = 0, fy = 0, potential = 0;
  for (const [wx, wy, m] of wells) {
    const dx = wx-x, dy = wy-y, d2 = dx*dx+dy*dy+400, d = Math.sqrt(d2);
    fx += dx/d*m/d2*800; fy += dy/d*m/d2*800;
    potential -= m*200/d;
  }
  const kinetic = Math.sqrt(fx*fx+fy*fy);
  const totalE = Math.tanh((potential+kinetic*50)*0.01);
  const turb = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const sx = x+fx*0.15+turb+Math.sin(y*0.025-t*0.4)*8;
  const sy = y+fy*0.15+Math.cos(x*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*8;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [60+Math.sin(t*0.7+3)*50, 40+Math.cos(t*0.5)*30, 0.14, 2.1],
    [420+Math.cos(t*0.45)*60, 220+Math.sin(t*0.65+2)*40, 0.11, 1.8]
  ];
  let aS = 0, iS = 0, bS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp);
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5);
    bS += Math.sin(d*f*0.5-t*sp*0.4+3.0);
  }
  const act = aS/8, inh = iS/8, bic = bS/8;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(kinetic*0.1+t)*0.15;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const eBlend = Math.sin(totalE*Math.PI*2+t)*0.5;
  const reaction = Math.tanh((act-inh*0.7+bg*0.3+spiral+bic*0.2+eBlend)*2.2);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const dxR = Math.abs(reaction-Math.tanh((Math.sin((sx+1)*0.04+sy*0.025+t*0.8))*0.5));
  const dyR = Math.abs(reaction-Math.tanh((Math.sin(sx*0.04+(sy+1)*0.025+t*0.8))*0.5));
  const edge = Math.min(1, (dxR+dyR)*8);
  const blend = reaction*0.7+cell*0.2+edge*0.1, v = blend*0.5+0.5;
  const pal = [[2,2,15],[10,10,60],[0,180,255],[0,255,140],[255,255,0],[255,50,150],[200,0,255],[50,0,120],[2,2,15]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const glow = Math.max(0, Math.abs(reaction)-0.5)*2;
  const lum = 0.7+glow*0.8+Math.sin(reaction*Math.PI)*0.2;
  const nBoost = Math.abs(reaction)>0.6?1.3:1.0, eBoost = edge>0.3?1.2:1.0, m = lum*nBoost*eBoost;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m+glow*20)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m+glow*40)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m+glow*60)|0
  ];
}
